function collectLetIndices(n) {
  const out = [];
  for (let i = 0; i < n; i += 1) {
    out.push((() => i)());
  }
  return out;
}

function varHoistSnapshot() {
  return (function () {
    const typeofResult = typeof x;
    var x = 5;
    return [typeofResult, x];
  })();
}

